# Tool modules decide what to run. This file decides how.
version: '3'

tasks:
  run:
    requires:
      vars: [IMAGE, CMD, PROJECT_ROOT]
    vars:
      # the caller's vars, project settings included
      context:
        ref: '.TASK_CONTEXT | default .'
      # settings, each with a default
      engine: '{{.context.CONTAINER_ENGINE | default "docker"}}'
      mount: '{{.context.CONTAINER_MOUNT_MODE | default "rw"}}'
      envs: '{{.context.CONTAINER_ENVS | default ""}}'
      ports: '{{.context.CONTAINER_PORTS | default ""}}'
    cmds:
      - |
        # fixed for every tool: no root, no capabilities
        set -- {{.engine}} run --rm --init \
          --cap-drop ALL --security-opt no-new-privileges \
          --user "$(id -u):$(id -g)" --env HOME=/tmp \
          --volume {{.PROJECT_ROOT | shellQuote}}:/workspace:{{.mount}} \
          --workdir /workspace/{{.WORKDIR | default "."}}
        # the cache stays on the host between runs
        {{if .CACHE_DIR}}
        mkdir -p {{.PROJECT_ROOT | shellQuote}}/{{.CACHE_DIR}}
        set -- "$@" --volume {{.PROJECT_ROOT | shellQuote}}/{{.CACHE_DIR}}:{{.CACHE_TARGET}}
        {{end}}
        {{range .ENVS}}set -- "$@" --env {{. | shellQuote}}
        {{end}}
        {{range (.envs | splitArgs)}}set -- "$@" --env {{.}}
        {{end}}
        {{range (.ports | splitArgs)}}set -- "$@" --publish {{.}}
        {{end}}
        exec "$@" {{.IMAGE}} {{.CMD}}

deploy:
  needs: build
  uses: …/cd-aws-s3-static.yml@v2
  permissions:
    contents: read
    id-token: write # the job gets short-lived AWS keys, no stored secrets
  with:
    aws-role-arn: ${{ vars.AWS_DEPLOY_ROLE_ARN }}
    aws-region: ${{ vars.AWS_REGION }}
    domain-name: ${{ vars.SITE_DOMAIN_NAME }}
    site-bucket-name: ${{ vars.SITE_BUCKET_NAME }}
